#include "../src/game/pickup_hud.hpp"
int main(int argc,char**argv){if(argc!=2)return 1;shin::AssetStore a(argv[1]);shin::PlayerPayload p;shin::initialize_player_payload(p,0,0);shin::IndexedSurface f(640,480,254),expected(640,480,254);for(int value:{0,1,9,10,99,100,123456,999999}){p.at(0x70)=value;f.clear(254);expected.clear(254);shin::draw_pickup_hud(a,p,f);auto str=std::to_string(value);str=std::string(6-str.size(),'0')+str;for(int i=0;i<6;++i)expected.blit(a.image(std::string(1,str[i])+".app"),10+32*i,10);if(f.pixels!=expected.pixels)return 2;}p.at(0x70)=0;f.clear(254);shin::draw_pickup_hud(a,p,f);auto old=f.pixels;++p.at(0xec);++p.at(0x70);f.clear(254);shin::draw_pickup_hud(a,p,f);if(f.pixels==old)return 3;shin::IndexedSurface wide(853,480,254),wide_expected(853,480,254);wide.origin_x=106;p.at(0x70)=123456;shin::draw_pickup_hud(a,p,wide);for(int i=0;i<6;++i)wide_expected.blit(a.image(std::to_string(i+1)+".app"),10+32*i,10);if(wide.pixels!=wide_expected.pixels)return 4;return 0;}
